// Self-authored line-art motifs (Gate E): drawn for this project as SVG line work and rasterised to transparent PNG
// (source: motifs.make.html). Decorative only, never data-bearing. Original work, no third-party content.
export interface Motif { w: number; h: number; png: string; provenance: string; themes: string[] }
export const MOTIFS: Record<string, Motif> = {
  paris: { w: 300, h: 420, provenance: 'self-authored line art (Gate E)', themes: ["sovereign", "france", "country", "government"], png: 'data:image/png;base64,' },
  finance: { w: 420, h: 300, provenance: 'self-authored line art (Gate E)', themes: ["banking", "finance", "fiscal", "debt", "markets"], png: 'data:image/png;base64,' },
  infrastructure: { w: 520, h: 240, provenance: 'self-authored line art (Gate E)', themes: ["infrastructure", "transport", "energy"], png: 'data:image/png;base64,' },
  insurance: { w: 320, h: 320, provenance: 'self-authored line art (Gate E)', themes: ["insurance", "reinsurance", "risk"], png: 'data:image/png;base64,' },
  macro: { w: 320, h: 320, provenance: 'self-authored line art (Gate E)', themes: ["macro", "geopolitics", "global", "trade"], png: 'data:image/png;base64,' },
  technology: { w: 320, h: 320, provenance: 'self-authored line art (Gate E)', themes: ["technology", "semiconductor", "digital", "ai"], png: 'data:image/png;base64,' },
}
/** the motif for a slide's subject keywords, or null */
export function motifFor(words: string[]): string | null {
  const w = words.map((x) => x.toLowerCase())
  for (const [k, m] of Object.entries(MOTIFS)) if (m.themes.some((t) => w.includes(t))) return k
  return null
}
